'use strict';(function(root){const cache=new Map;function image(slot){if(!cache.has(slot)){const im=new Image;im.src='rpg-fx/idol/idol-'+slot+'.svg';cache.set(slot,im);}return cache.get(slot);}function strip(p,slot,x,y,t,w,h,angle=0,alpha=1){const im=image(slot);if(!im.complete||!im.naturalWidth)return;p.save();p.globalAlpha*=alpha;p.translate(x,y);p.rotate(angle);p.imageSmoothingEnabled=false;const frame=Math.min(7,Math.max(0,Math.floor(t*8)));p.drawImage(im,frame*256,0,256,256,-w/2,-h/2,w,h);p.restore();}
function active(g){return g.s.active===6&&g.h.cell===6&&g.c?.idol;}
function ground(p,g,t){const i=active(g);if(!i)return;const c=g.c;if(i.stage>0||i.encore>0){strip(p,1,c.x,c.y-28,t%1,i.encore>0?250:180,i.encore>0?180:145,0,i.encore>0?.85:.65);if(i.encore>0){p.save();for(const side of [-1,1]){p.fillStyle='#172332';p.fillRect(c.x+side*94-13,c.y-35,26,46);p.strokeStyle='#8398aa';p.lineWidth=2;p.strokeRect(c.x+side*94-13,c.y-35,26,46);for(const yy of [-23,-4]){p.fillStyle='#a8bcd0';p.beginPath();p.arc(c.x+side*94,c.y+yy,7,0,Math.PI*2);p.fill();p.fillStyle='#263a4f';p.beginPath();p.arc(c.x+side*94,c.y+yy,3,0,Math.PI*2);p.fill();}}p.restore();}}}
function state(p,g,t){const i=active(g);if(!i)return;for(const s of i.shots)strip(p,0,s.x,s.y,(t*3)%1,s.basic?37:51,s.basic?30:45,Math.atan2(s.vy,s.vx));p.save();const c=g.c;p.fillStyle='#162833';p.fillRect(c.x-29,c.y-89,58,5);p.fillStyle=i.popularity>=60?'#ecdda6':'#a7d7ea';p.fillRect(c.x-29,c.y-89,58*i.popularity/100,5);p.textAlign='center';p.font='bold 10px sans-serif';p.fillStyle='#e4f3f1';p.fillText('인기 '+Math.floor(i.popularity)+'/100',c.x,c.y-94);p.restore();}
function draw(p,f,t){if(f.heroId!==6||f.cell!==6)return false;if(t<0||t>1.3)return true;const o=f.from||f,k=f.idolKind;if(!f.phase){if(f.slot===0)strip(p,0,o.x+12,o.y-36,t,45,40,0,Math.max(0,1-t));else if(f.slot===1){p.save();p.globalAlpha*=Math.max(0,1-t/.7);p.fillStyle='#d7e8ef';for(let j=0;j<3;j++)p.fillRect(o.x-28+j*25,o.y-70-t*10,7,3);p.restore();}else if(f.slot===2)strip(p,2,o.x+45,o.y-10,t,120,90,0,Math.max(0,1-t));else strip(p,3,o.x,o.y-15,t,160,120,0,Math.max(0,1-t));return true;}if(k==='beat-hit')strip(p,0,f.x,f.y-20,t,70,65,Math.PI/2,Math.max(0,1-t));if(k==='step-hit')strip(p,2,f.x+Math.cos(f.angle)*112,f.y-15+Math.sin(f.angle)*112,t,330,240,f.angle,Math.max(0,1-t));if(k==='encore-hit')strip(p,3,f.x,f.y-25,t,360,230,0,Math.max(0,1-t/1.2));return true;}
function preload(){for(let i=0;i<4;i++)image(i);}root.RPG_IDOL_FX={draw,state,ground,preload};})(typeof window!=='undefined'?window:globalThis);
